<?php
namespace App\Modules\Orders\Http\Controllers;
use App\Http\Controllers\Controller;
use App\Models\User;
use App\Modules\Inventories\Products\Models\Product;
use App\Modules\Inventories\Products\Models\ProductVariant;
use App\Modules\Orders\Services\DeliveryChargeCalculator;
use App\Modules\Settings\Models\WebsiteSetting;
use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Inertia\Inertia;
use Inertia\Response;
class ManualOrderController extends Controller {
 public function create(): Response { $products=Product::query()->with(['variants'=>fn($q)=>$q->where('is_active',true)])->whereIn('status',['Published','Active'])->orderBy('title')->get(); return Inertia::render('app/modules/orders/pages/Create',['products'=>$products->map(fn(Product $p)=>['id'=>$p->id,'title'=>$p->title,'sku'=>$p->sku,'price'=>(float)$p->current_price,'stock'=>(int)$p->stock_quantity,'image'=>$p->featured_image_path?'/image/'.rawurlencode(basename(str_replace('\\','/',$p->featured_image_path))):null,'variants'=>$p->variants->map(fn(ProductVariant $v)=>['id'=>$v->id,'name'=>$v->name,'sku'=>$v->sku,'price'=>(float)$v->current_price,'stock'=>(int)$v->stock_quantity])->values()])->values(),'customers'=>User::query()->where('is_admin',false)->orderBy('name')->get(['id','name','phone','email'])->map(fn(User $u)=>['id'=>$u->id,'name'=>$u->name,'phone'=>$u->phone,'email'=>$u->email])]); }
 public function store(Request $request,DeliveryChargeCalculator $calculator): RedirectResponse { $data=$request->validate(['source'=>['required',Rule::in(['phone','whatsapp','manual'])],'user_id'=>['nullable','integer','exists:users,id'],'customer_name'=>['required','string','max:120'],'phone'=>['required','string','max:30'],'email'=>['nullable','email','max:255'],'address'=>['required','string','max:1000'],'city'=>['required','string','max:120'],'delivery_zone'=>['required',Rule::in(['inside_dhaka','outside_dhaka'])],'note'=>['nullable','string','max:2000'],'payment_method'=>['required',Rule::in(['cod'])],'payment_status'=>['required',Rule::in(['pending','paid'])],'discount'=>['nullable','numeric','min:0'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','integer','exists:products,id'],'items.*.variant_id'=>['nullable','integer','exists:product_variants,id'],'items.*.quantity'=>['required','integer','min:1','max:999'],'items.*.unit_price'=>['required','numeric','min:0']]); if(filled($data['user_id']??null))abort_if(User::query()->whereKey($data['user_id'])->where('is_admin',true)->exists(),422,'An admin account cannot be selected as a customer.'); $orderId=DB::transaction(function()use($data,$request,$calculator){$products=Product::query()->whereIn('id',collect($data['items'])->pluck('product_id'))->lockForUpdate()->get()->keyBy('id');$variants=ProductVariant::query()->whereIn('id',collect($data['items'])->pluck('variant_id')->filter())->lockForUpdate()->get()->keyBy('id');$settings=WebsiteSetting::firstOrCreate(['id'=>1]);$allow=(bool)($settings->allow_out_of_stock_orders??true);$subtotal=0.0;$short=false;$prepared=[];$deliveryLines=collect();foreach($data['items'] as $line){$product=$products->get($line['product_id']);$variant=filled($line['variant_id']??null)?$variants->get($line['variant_id']):null;abort_unless($product&&in_array($product->status,['Published','Active'],true),422,'One or more products are unavailable.');abort_if($variant&&(int)$variant->product_id!==(int)$product->id,422,'The selected variant does not belong to its product.');$stock=(int)($variant?->stock_quantity??$product->stock_quantity);abort_if(!$allow&&$stock<$line['quantity'],422,$product->title.' does not have enough stock.');$price=round((float)$line['unit_price'],2);$lineTotal=$price*$line['quantity'];$subtotal+=$lineTotal;$shortage=max(0,$line['quantity']-$stock);$short=$short||$shortage>0;$prepared[]=compact('product','variant','stock','shortage','price','lineTotal')+['quantity'=>(int)$line['quantity']];$deliveryLines->push(['product'=>$product,'quantity'=>(int)$line['quantity']]);}$discount=min(round((float)($data['discount']??0),2),$subtotal);$delivery=$calculator->calculate($settings,$deliveryLines,$subtotal-$discount,$data['delivery_zone'],$data['payment_method']);$number='#ORD'.str_pad((string)((int)DB::table('orders')->max('id')+1),2,'0',STR_PAD_LEFT);$now=now();$id=DB::table('orders')->insertGetId(['order_number'=>$number,'source'=>$data['source'],'user_id'=>$data['user_id']??null,'customer_name'=>$data['customer_name'],'phone'=>$data['phone'],'email'=>$data['email']??null,'address'=>$data['address'],'city'=>$data['city'],'delivery_zone'=>$data['delivery_zone'],'note'=>$data['note']??null,'payment_method'=>$data['payment_method'],'payment_status'=>$data['payment_status'],'payment_status_updated_at'=>$data['payment_status']==='paid'?$now:null,'payment_status_updated_by'=>$data['payment_status']==='paid'?$request->user()->id:null,'status'=>'pending','subtotal'=>$subtotal,'discount_total'=>$discount,'shipping_total'=>$delivery['shipping'],'cod_surcharge'=>$delivery['cod'],'delivery_breakdown'=>json_encode($delivery),'total'=>$subtotal-$discount+$delivery['total'],'has_stock_shortage'=>$short,'created_at'=>$now,'updated_at'=>$now]);foreach($prepared as $line){DB::table('order_items')->insert(['order_id'=>$id,'product_id'=>$line['product']->id,'product_variant_id'=>$line['variant']?->id,'product_title'=>$line['product']->title,'variant_name'=>$line['variant']?->name,'sku'=>$line['variant']?->sku?:$line['product']->sku,'unit_price'=>$line['price'],'quantity'=>$line['quantity'],'line_total'=>$line['lineTotal'],'stock_shortage_quantity'=>$line['shortage'],'created_at'=>$now,'updated_at'=>$now]);if($line['variant']&&$line['stock']>0)$line['variant']->decrement('stock_quantity',min($line['stock'],$line['quantity']));elseif(!$line['variant']&&$line['stock']>0)$line['product']->decrement('stock_quantity',min($line['stock'],$line['quantity']));}return $id;});return to_route('orders.show',$orderId)->with('success','Manual order created successfully.'); }
}
